O("w663347632", "אנדרטת חללי המלחמה הגדולה", "Monument to the Dead of the Great War", 38.719504, -9.145264, "אנדרטה", ["h2"],
  "אנדרטת אבן וברונזה לזכר החיילים הפורטוגלים שנפלו במלחמת העולם הראשונה, ולכבוד הלוחמים ששרדו. היא עומדת באמצע אבנידה דה ליברדדה, ומעידה על פרק שפחות מוכר למבקרים: השתתפות פורטוגל במלחמה בחזית בפלנדריה ובאפריקה.",
  "על אבנידה דה ליברדדה, ברצועה המרכזית של השדרה, בפינת רואה דו סליטרה. תחנת המטרו אבנידה קרובה.",
  "פורטוגל נכנסה למלחמת העולם הראשונה ב-1916, לאחר שגרמניה הכריזה עליה מלחמה. חיל משלוח פורטוגלי נשלח לחזית המערבית בפלנדריה, ובקרב לה ליס באפריל 1918 ספג אבדות כבדות. במקביל נלחמו כוחות פורטוגליים במושבות באנגולה ובמוזמביק. המלחמה הותירה רושם עמוק בפורטוגל של הרפובליקה הראשונה, ובשנות ה-20 וה-30 הוקמו אנדרטאות לזכר הנופלים בערים רבות.\nלפי OSM, האנדרטה בליסבון היא מעשה ידי הפסל מקסימיאנו אלווש, והיא נחנכה ב-1931. היא הוקמה, כלשון התיאור ב-OSM, לזכר המתים ולתהילת הלוחמים החיים. האנדרטה משלבת פסלי ברונזה, בסיס אבן וכתובות.",
  "מקסימיאנו אלווש (1888-1954) יצר גם את אנדרטת העיתונאי פרנסה בורז'ש בגן פרינסיפה ריאל, הקרוב לכאן. האבנידה עצמה נפתחה בשנות ה-80 של המאה ה-19 במקום הפסאיו פובליקו, הטיילת הציבורית מתקופת המרקיז דה פומבל, ולאורכה פזורים פסלים, מזרקות ובריכות. לאנדרטה ערך בוויקיפדיה האנגלית והפורטוגלית.",
  ["לפי OSM האנדרטה נחנכה ב-1931.", "בקרב לה ליס (1918) ספג הכוח הפורטוגלי אבדות כבדות."],
  "משלבים בטיול לאורך האבנידה: פסלי הטז'ו והדורו בבריכות, פסל חזה של שופן, ובהמשך כיכר המרקיז דה פומבל.", w=1, yr="1931", by="מקסימיאנו אלווש", s=7.8, b=1),

O("n5457851380", "פסל מרקוריו", "Mercúrio (Mercury)", 38.720189, -9.149122, "פסל", ["h3"],
  "פסל ברונזה של מרקוריוס, אל המסחר והשליחים במיתולוגיה הקלאסית, שהזמינה איגוד הסוחרים של מחוז ליסבון מאחד הפסלים החשובים בפורטוגל של המאה ה-20, לאופולדו דה אלמיידה. בחירה מתבקשת לאל המסחר בעיר נמל.",
  "בשולי פרינסיפה ריאל, באזור שבין רואה דה אשקולה פוליטקניקה ובין אבנידה דה ליברדדה, כ-150 מטרים מהאתר 'אוכל כשר בליסבון' שבמדריך.",
  "לפי OSM, הפסל הוצב ב-1968 ביוזמת איגוד הסוחרים של מחוז ליסבון (Associação dos Comerciantes do Distrito de Lisboa), והוא מציג את מרקוריוס כ'מבשר', שליח האלים. במיתולוגיה הרומית, ובמקבילה היוונית הרמס, הוא אל המסחר, הדרכים והשליחים, ולכן הפך לסמל מקובל של סוחרים, בנקים ומוסדות כלכליים.\nלאופולדו דה אלמיידה (1898-1975) היה מהפסלים המרכזיים בפורטוגל במאה ה-20. הוא יצר את רוב הדמויות באנדרטת התגליות בבלם ואת הפסל הרכוב של ז'ואאו הראשון בפראסה דה פיגיירה. ב-OSM אין פרטים נוספים על מראה הפסל, והתיאור כאן נשען על הנתונים הקיימים.",
  "הפסל משנת 1968 שייך לשלב המאוחר בפעילותו של לאופולדו דה אלמיידה, שבו יצר פסלים רבים למוסדות ציבוריים. מרקוריוס מוצג באמנות לרוב עם קסדה מכונפת, סנדלים מכונפים ומטה השליחים (הקדוקאוס), סמלים שמזהים אותו מיד. האזור שסביב הפסל משלב רחובות מגורים, בתי עסק ומבנים מהמאה ה-19.",
  ["לפי OSM הפסל הוצב ב-1968 ביוזמת איגוד הסוחרים של מחוז ליסבון.", "לאופולדו דה אלמיידה יצר גם את רוב הדמויות באנדרטת התגליות."],
  "משלבים בהליכה בין גן פרינסיפה ריאל לגן הבוטני ולמוזיאון הלאומי לטבע ולמדע.", w=0, yr="1968", by="לאופולדו דה אלמיידה", s=7.0, b=1),

O("n5457844741", "פסל חזה של פדרו אלוורש קברל", "Pedro Álvares Cabral Bust (São Pedro de Alcântara)", 38.715355, -9.14401, "פסל חזה", ["h1", "ppl"],
  "פסל חזה דקורטיבי באבן של פדרו אלוורש קברל, הספן שהגיע לחופי ברזיל בשנת 1500. הוא אחד מסדרת פסלי חזה של דמויות מתקופת התגליות שבגן המירדורו סאו פדרו דה אלקנטרה, אחת מנקודות התצפית הגדולות של ליסבון.",
  "בגן של מירדורו סאו פדרו דה אלקנטרה, בראש מעלית הגלוריה, בין פסלי החזה של ושקו דה גאמה, קמואש ואפונסו דה אלבוקרקי.",
  "פדרו אלוורש קברל (בערך 1467-1520) עמד בראש הצי השני שיצא מליסבון להודו, ב-1500, אחרי מסעו של ושקו דה גאמה. בדרכו, כשהצי התרחק מערבה באוקיינוס האטלנטי, הגיע לחוף שאותו כינה 'ארץ הצלב האמיתי', היא ברזיל של היום. הצי המשיך משם לקליקוט שבהודו, ואיבד בדרך כמה ספינות. קברל נקבר בסנטרן.\nבגן של סאו פדרו דה אלקנטרה עומדת שורה של פסלי חזה באבן של מלכים, ספנים, מושלים והיסטוריונים מתקופת ההתפשטות הפורטוגלית. לפי OSM, פסל החזה של קברל מיוחס לרודולפו ברנרדלי ולשנת 1940, אך ברנרדלי ידוע כיוצר פסל קברל בריו דה ז'ניירו, שהעתק שלו הוצב ב-1940 בשדרת פדרו אלוורש קברל בליסבון; ייתכן שהנתונים ב-OSM מתייחסים לפסל ההוא.",
  "הגן של סאו פדרו דה אלקנטרה בנוי בשתי טרסות, ומהעליונה נשקף נוף רחב אל הבאישה, אל הקאשטלו ואל גראסה. לאורך הגן פזורים פסלי חזה רבים, ולפי המסופר גם דמויות מהמיתולוגיה. האזור תוסס בערבים, ופועלים בו קיוסקים. מעלית הגלוריה, שעולה מהרשטאורדורש, מגיעה בדיוק לכאן.",
  ["קברל הגיע לחופי ברזיל באפריל 1500.", "לפי OSM הפסל מיוחס לרודולפו ברנרדלי ולשנת 1940, נתון שאינו ודאי."],
  "עוברים בין פסלי החזה בגן ומסיימים בתצפית אל הקאשטלו, ואחר כך יורדים במעלית הגלוריה.", w=0, yr="", by="", s=6.8, b=1),

O("n4852004199", "'אני כמוך' של רואי שאפש", "Sou Como Tu (I Am Like You)", 38.722382, -9.147199, "פיסול מופשט", ["abs", "h3"],
  "פסל ברזל מחושל בגובה שישה מטרים ובמשקל של כטון, של רואי שאפש, מהפסלים הבולטים בפורטוגל של היום. צורה אורגנית ודקה שמתנשאת לגובה, ומשחקת בין הכובד של המתכת לתחושה של קלילות. השם 'אני כמוך' מזמין את הצופה לראות בו דמות.",
  "מערבית לחלקה העליון של אבנידה דה ליברדדה, כ-95 מטרים מבית חב\"ד ליסבון שבמדריך.",
  "רואי שאפש, יליד ליסבון (1966), עובד מאז שנות ה-80 בעיקר בברזל ובפלדה, ויוצר פסלים שצבועים לרוב בשחור ונראים כמו צורות צמחיות, עצמות או כלים מסתוריים. הוא ידוע בזיקתו לרומנטיקה הגרמנית, ותרגם לפורטוגלית כתבים של המשורר נובליס. הכותרות של עבודותיו הן לעיתים קרובות משפטים שיריים, כמו Sou Como Tu, שהופכים את הפסל לבן שיח של הצופה.\nלפי OSM, הפסל הוצב ב-2008. זו עבודה של ברזל מחושל בגובה שישה מטרים, שמשקלה כטון. הפסל עומד במרחב העירוני הפתוח, וזו הזדמנות לראות עבודה של שאפש שלא בתוך מוזיאון.",
  "עבודות של רואי שאפש מוצגות במוזיאונים ובאוספים בפורטוגל ומחוץ לה, ובליסבון אפשר למצוא אותן גם במקומות ציבוריים נוספים. באור של שעות הבוקר המאוחרות ושל אחר הצהריים, הצללית השחורה של הפסל בולטת על רקע השמיים. לפסל יש פריט בוויקידאטה בשם האנגלי I Am Like You.",
  ["לפי OSM הפסל בגובה 6 מטרים ומשקלו כטון.", "הוצב ב-2008."],
  "משלבים בהליכה מגן פרינסיפה ריאל אל מרקוריו ואל האבנידה.", w=1, yr="2008", by="רואי שאפש", s=7.0, b=1),

O("n5457844785", "הטז'ו והדורו", "Tejo e Douro (Alexandre Gomes, 1780)", 38.718106, -9.144045, "מזרקה", ["fnt", "h1"],
  "שני פסלי מזרקה גדולים מאבן מ-1780, של אלכסנדר גומש, שמגלמים את שני הנהרות הגדולים של פורטוגל: הטז'ו והדורו. כל נהר מוצג כדמות גברית דמוית אל, מעט גדולה מגודל טבעי, וביחד הם מהפסלים הוותיקים ביותר באבנידה דה ליברדדה.",
  "באבנידה דה ליברדדה, ליד הבריכות שבמרכז השדרה, בקטע שבין הרשטאורדורש לפראסה דה אלגריה. כ-130 מטרים מהוט קלוב דה פורטוגל.",
  "לפי OSM, שני הפסלים עשויים אבן ונוצרו ב-1780 בידי אלכסנדר גומש. הדורו מוצג כדמות גברית דמוית אל, 'מתבונן בהתפתחות הגדות', כלשון התיאור, והטז'ו מקביל לו כדמות תאומה. זו מסורת קלאסית: כבר ברומא העתיקה הוצגו נהרות כגברים מזוקנים שוכבים או יושבים, שממיהם יוצאים המים, והמסורת חזרה במזרקות הבארוק ובפסלי הגנים באירופה.\nלפי המסופר, הפסלים היו חלק מהעיצוב של הטיילת הציבורית שנפתחה אחרי רעידת האדמה של 1755 במקום שבו עוברת היום האבנידה, הפסאיו פובליקו, ונשארו כשהטיילת הפכה בשנות ה-80 של המאה ה-19 לשדרה הרחבה. הם עומדים כיום ליד הבריכות שלאורך השדרה.",
  "הטז'ו והדורו הם שני הנהרות הגדולים של פורטוגל, ושניהם נובעים בספרד: הטז'ו נשפך לאוקיינוס בליסבון, והדורו בפורטו. הצבתם יחד הייתה דרך להציג את הממלכה כולה, מצפון ועד דרום. אלכסנדר גומש היה פסל ליסבונאי בתקופה שלאחר רעידת האדמה, כשהעיר נבנתה מחדש ונדרשו פסלים רבים למזרקות, לגנים ולחזיתות.",
  ["לפי OSM שני הפסלים הם מ-1780, של אלכסנדר גומש.", "הכרטיס מאחד את פסל הדורו ואת פסל הטז'ו."],
  "מחפשים את שני הנהרות זה מול זה, וממשיכים במעלה האבנידה אל אנדרטת המלחמה הגדולה.", w=0, yr="1780", by="אלכסנדר גומש", s=7.2, b=1,
  kids="שני ענקים מאבן, כל אחד מהם הוא נהר! הטז'ו הוא הנהר של ליסבון והדורו הוא הנהר של פורטו. אפשר לנחש מי מהם הוא מי, ולחפש איפה זורמים המים."),

# --- פסלי החזה בגן סאו פדרו דה אלקנטרה ---
O("n5457844754", "פסל חזה של אפונסו דה אלבוקרקי", "Afonso de Albuquerque Bust (São Pedro de Alcântara)", 38.715452, -9.144216, "פסל חזה", ["h1", "ppl"],
  "פסל חזה דקורטיבי באבן של אפונסו דה אלבוקרקי, משנה המלך של הודו בשנים 1508-1515, אחד מסדרת פסלי החזה בגן המירדורו סאו פדרו דה אלקנטרה.",
  "בגן של מירדורו סאו פדרו דה אלקנטרה, בראש מעלית הגלוריה, בשורת פסלי החזה שלצד פסלי קברל וקמואש.",
  "אפונסו דה אלבוקרקי (בערך 1453-1515) היה מושל ההתיישבות הפורטוגלית בהודו, ובתקופתו השתלטה פורטוגל על גואה (1510), על מלאקה (1511) ועל הורמוז, נקודות מפתח בנתיבי הסחר באוקיינוס ההודי. הוא מת בים ליד גואה ב-1515. ב-OSM אין פרטים על האמן ועל שנת ההצבה של פסל החזה.",
  "", ["לפי OSM, אלבוקרקי היה משנה המלך של הודו בשנים 1508-1515."],
  "עוברים בין פסלי החזה בגן ומשווים בין הדמויות.", w=0, yr="", by=""),

O("n5457851258", "פסל חזה של ז'ואאו דה קשטרו", "D. João de Castro Bust (São Pedro de Alcântara)", 38.715215, -9.144071, "פסל חזה", ["h1", "ppl"],
  "פסל חזה דקורטיבי באבן של ז'ואאו דה קשטרו, המושל ה-14 ומשנה המלך הרביעי של הודו הפורטוגלית, בגן המירדורו סאו פדרו דה אלקנטרה.",
  "בגן של מירדורו סאו פדרו דה אלקנטרה, בשורת פסלי החזה של דמויות מתקופת התגליות, כמה עשרות מטרים מראש מעלית הגלוריה.",
  "ז'ואאו דה קשטרו (1500-1548) היה ספן, איש מדע ומושל. ביומני המסע שכתב בים האדום ובאוקיינוס ההודי תיעד מדידות של סטיית המצפן ותצפיות טבע, והוא נחשב לאחד מאנשי המדע הימי החשובים של פורטוגל במאה ה-16. ב-1546 הוביל את הסרת המצור מעל דיו, ומונה למשנה המלך זמן קצר לפני מותו בגואה. ב-OSM אין פרטים על האמן ועל השנה.",
  "", ["לפי OSM, ז'ואאו דה קשטרו היה המושל ה-14 ומשנה המלך הרביעי של הודו."],
  "משלבים בסיור בין פסלי החזה, ואחר כך בתצפית אל הקאשטלו.", w=0, yr="", by=""),

O("n5457851378", "פסל חזה של המלך מנואל הראשון", "D. Manuel I Bust (São Pedro de Alcântara)", 38.715379, -9.144236, "פסל חזה", ["h1", "ppl", "jew"],
  "פסל חזה דקורטיבי באבן של מנואל הראשון (1469-1521), 'בר המזל', המלך ה-14 של פורטוגל, שבימיו יצאו המסעות להודו ולברזיל. אחד מפסלי החזה שבגן סאו פדרו דה אלקנטרה.",
  "בגן של מירדורו סאו פדרו דה אלקנטרה, בראש מעלית הגלוריה, בשורת פסלי החזה.",
  "מנואל הראשון מלך בשנים 1495-1521. בתקופתו הגיע ושקו דה גאמה להודו, קברל הגיע לברזיל, ועושר הסחר במזרח מימן את מנזר ז'רונימוש ואת מגדל בלם, ונתן את שמו לסגנון המנואלי. בתקופתו גם הוצאה ב-1496 גזירת הגירוש של יהודי פורטוגל, שהפכה ב-1497 להמרה כפויה, ובליסבון אירע הטבח של 1506. ב-OSM אין פרטים על האמן ועל השנה של פסל החזה.",
  "", ["לפי OSM, מנואל הראשון היה המלך ה-14 של פורטוגל."],
  "מי שמתעניין במורשת היהודית יכול לשלב את אנדרטת 1506 ליד כנסיית סאו דומינגוש, בירידה לרוסיו.", w=0, yr="", by=""),

