O("w1559418823", "אסטלת נישואי המלך לואיש הראשון", "Consórcio de Dom Luís (Stele)", 38.713159, -9.143104, "אנדרטה", ["h1"],
  "אסטלת אבן מ-1862 שהקימה הקהילה האיטלקית בליסבון לכבוד נישואי המלך לואיש הראשון עם הנסיכה מריה פיה מסבויה. עדות קטנה לקשר בין בית המלוכה הפורטוגלי לבית סבויה האיטלקי.",
  "בלארגו טרינדדה קואליו, מול כנסיית סאו רוקה, צמוד לפסל 'מוכר הכרטיסים' ולפסל פדרה אנטוניו ויירה.",
  "לפי OSM, האסטלה הוקמה ביוזמת המושבה האיטלקית שגרה בליסבון, לציון נישואי לואיש הראשון ומריה פיה מסבויה, שנחגגו ב-6 באוקטובר 1862. מריה פיה הייתה בתו של ויטוריו אמנואלה השני, מלך איטליה המאוחדת, והנישואים חיזקו את הקשר בין שתי הממלכות. לואיש הראשון מלך בפורטוגל בשנים 1861-1889. ב-OSM רשום שהאמן אינו ידוע.",
  "", ["לפי OSM החתונה נחגגה ב-6 באוקטובר 1862."],
  "שלוש יצירות בכיכר אחת: האסטלה, מוכר הכרטיסים ופדרה ויירה.", w=0, yr="1862", by=""),

O("n5457851374", "פסל מופשט ליד מנזר האינגלזיניוש", "Sculpture by the former Convento dos Inglesinhos", 38.712893, -9.146368, "פיסול מופשט", ["abs"],
  "פסל מופשט מברזל שמוצמד לגוש אבן, ליד מנזר האינגלזיניוש לשעבר בביירו אלטו. יצירה עכשווית ושקטה בסמטאות השכונה.",
  "בביירו אלטו, ליד בניין מנזר האינגלזיניוש לשעבר, ברחוב בעל אותו שם, כ-130 מטרים מאזור חיי הלילה של השכונה.",
  "לפי OSM, הפסל עשוי ברזל על גוש אבן, והוא ככל הנראה של מנואל קרנה, אך גם ב-OSM השיוך מסומן בסימן שאלה. שנת ההצבה מוערכת שם בסביבות שנת 2000. 'האינגלזיניוש', 'האנגלים הקטנים', הוא כינוי המכללה האנגלית שפעלה כאן מהמאה ה-17 והכשירה כמרים קתולים מאנגליה, בתקופה שבה הקתוליות הייתה אסורה שם.",
  "", ["לפי OSM, הפסל הוצב בסביבות 2000; שם האמן מסומן בסימן שאלה."],
  "מגיעים ביום, כשהסמטאות שקטות, ומשלבים עם הליכה אל מירדורו סנטה קתרינה.", w=0, yr="", by=""),

O("w1409362031", "אנדרטת פרנסה בורז'ש", "França Borges Monument", 38.716171, -9.14816, "פסל", ["h2", "ppl"],
  "אנדרטה מברונזה מ-1925 לעיתונאי הרפובליקני פרנסה בורז'ש: מדליון עם דיוקנו, ולצידו פסל בגודל טבעי של אישה שמגלמת את הרפובליקה. הגן של פרינסיפה ריאל נקרא רשמית על שמו, 'ז'רדים פרנסה בורז'ש'.",
  "בגן פרינסיפה ריאל (ז'רדים פרנסה בורז'ש), כ-40 מטרים מהכניסה, בין עצי הגן.",
  "אנטוניו פרנסה בורז'ש (1871-1915) היה עיתונאי ופוליטיקאי רפובליקני, ועמד בראש העיתון 'או מונדו', מהקולות הבולטים של התנועה הרפובליקנית לפני מהפכת 1910 ובשנותיה הראשונות של הרפובליקה. לפי OSM, האנדרטה הוקמה ביוזמת ועדה בראשות דומינגוש לייטה פריירה, והיא של הפסל מקסימיאנו אלווש, יוצר אנדרטת המלחמה הגדולה באבנידה.",
  "", ["לפי OSM האנדרטה מ-1925.", "דמות האישה בפסל מגלמת את הרפובליקה."],
  "משלבים עם העץ הגדול בגן פרינסיפה ריאל ועם הכניסה למאגר המים הפטריארכלי.", w=0, yr="1925", by="מקסימיאנו אלווש", s=6.8),

O("n4862637041", "אנדרטת אנטרו דה קנטל", "Memorial to Antero de Quental", 38.71579, -9.148779, "פיסול מופשט", ["abs", "ppl"],
  "פסל מופשט מאבן גיר, שיש ופלדה של לגואה אנריקש, יוצר פסל פסואה שליד א ברזיליירה, לזכר המשורר אנטרו דה קנטל במלאת מאה שנה למותו. נחנך ב-1991 בגן פרינסיפה ריאל.",
  "בגן פרינסיפה ריאל (ז'רדים פרנסה בורז'ש), כ-40 מטרים מהכניסה למאגר המים הפטריארכלי.",
  "אנטרו דה קנטל (1842-1891), יליד האיים האזוריים, היה משורר והוגה, ממובילי 'דור ה-70', חבורת אינטלקטואלים שקראה לחידוש התרבות והחברה בפורטוגל, ושאסה דה קיירוש היה מחבריה. הסונטות שלו נחשבות לאחת הפסגות של השירה הפורטוגלית במאה ה-19. לפי OSM, האנדרטה של לגואה אנריקש נחנכה ב-11 בספטמבר 1991, מאה שנה בדיוק אחרי מותו.",
  "", ["לפי OSM האנדרטה נחנכה ב-11 בספטמבר 1991."],
  "משלבים עם 'האמת' של אסה דה קיירוש, חברו מ'דור ה-70'.", w=0, yr="1991", by="לגואה אנריקש"),

O("n5672913435", "אנדרטה לזכר קורבנות ההומופוביה", "Monument to the Victims of Homophobia", 38.715972, -9.14845, "אנדרטה", ["h3"],
  "אנדרטה מבטון מזוין, בטון וברזל, עם לוח, לזכר קורבנות ההומופוביה, בגן פרינסיפה ריאל. נחנכה ב-2017 לפני מצעד הגאווה של ליסבון, ומשקפת את מקומה של השכונה כמרכז של הקהילה הגאה בעיר.",
  "בגן פרינסיפה ריאל (ז'רדים פרנסה בורז'ש), כ-30 מטרים מהכניסה למאגר המים הפטריארכלי, ליד אנדרטת אנטרו דה קנטל.",
  "לפי OSM, האנדרטה של רואי פריירה נחנכה ב-17 ביוני 2017, ימים אחדים לפני מצעד הגאווה (LGBT) של ליסבון. פרינסיפה ריאל ידועה כשכונה פתוחה ומגוונת, ובה ברים, חנויות עיצוב וגלריות, והיא קשורה כבר עשרות שנים לחיי הקהילה הגאה בעיר. פורטוגל אישרה נישואים חד־מיניים ב-2010.",
  "", ["לפי OSM האנדרטה נחנכה ב-17 ביוני 2017."],
  "משלבים בשיטוט בגן פרינסיפה ריאל ובחנויות שסביבו.", w=0, yr="2017", by="רואי פריירה"),

O("n4862637042", "פסל חזה של סוזה ויטרבו", "Sousa Viterbo Bust", 38.716536, -9.148763, "פסל חזה", ["ppl"],
  "פסל חזה מברונזה של סוזה ויטרבו, ארכאולוג וסופר, של הפסל פרנסישקו דוש סנטוש, שנחנך ב-1950 בפראסה דו פרינסיפה ריאל.",
  "בגן פרינסיפה ריאל, כשלושים מטרים מהאתר 'גן פרינסיפה ריאל' שבמדריך, בצד הצפוני של הכיכר.",
  "פרנסישקו מרקש דה סוזה ויטרבו היה חוקר, ארכאולוג וסופר פורטוגלי בסוף המאה ה-19 ובתחילת המאה ה-20, שכתב רבות על תולדות האמנות, האדריכלות והמלאכות בפורטוגל. לפי OSM, האנדרטה נחנכה ב-15 ביוני 1950, והיא כוללת פסל חזה מברונזה שעיצב הפסל פרנסישקו דוש סנטוש.",
  "", ["לפי OSM האנדרטה נחנכה ב-15 ביוני 1950."],
  "משלבים עם שאר היצירות בגן: פרנסה בורז'ש, אנטרו דה קנטל והאנדרטה לקורבנות ההומופוביה.", w=0, yr="1950", by="פרנסישקו דוש סנטוש"),

O("n5457844765", "פסל חזה של משאדו דה אסיס", "Machado de Assis Bust", 38.712328, -9.150261, "פסל חזה", ["ppl"],
  "פסל חזה מברונזה על בסיס שיש ואבן של משאדו דה אסיס, שנחשב לאחד מגדולי הסופרים של ברזיל. לפי OSM הוצב ב-2008, שנת המאה למותו.",
  "בשוליים המערביים של ביירו אלטו, כמאתיים מטרים מכנסיית סנטה קתרינה, בדרך לכיוון אשטרלה.",
  "ז'ואקים מריה משאדו דה אסיס (1839-1908), יליד ריו דה ז'ניירו, היה משורר, סופר, מחזאי ועיתונאי, ומייסד האקדמיה הברזילאית לספרות. הרומנים 'זיכרונות לאחר המוות של בראש קובאש' ו'דום קזמורו' נחשבים לפסגות הספרות בשפה הפורטוגלית. לפי OSM, פסל החזה הוצב ב-2008, מאה שנה אחרי מותו; האמן אינו ידוע.",
  "", ["לפי OSM פסל החזה הוצב ב-2008."],
  "משלבים עם מירדורו סנטה קתרינה והאדמסטור, כמה דקות הליכה מכאן.", w=0, yr="2008", by=""),
